"""Check plan_base against a reference DP that tries every start day."""
import sys

sys.path.insert(0, "/app/out")
import derive_report as dr


def reference(reqs, days, pool, m3, m23):
    n = len(reqs)
    if n == 0:
        return {0: (0, 0, 0, 0, (), ())}
    opts = []
    for r in reqs:
        per = []
        for c in range(0, r["max_compress"] + 1):
            length = r["duration"] - c
            per.append((c * r["shifts_per_day"], set(r["starts_by_length"][length]), length))
        opts.append(per)
    full = (1 << n) - 1
    zeros = (0,) * n
    layer = {(0, 0): (0, 0, 0, 0, zeros, zeros)}
    by_day = [dict() for _ in range(days + 3)]
    by_day[1] = layer
    best = {}
    for d in range(1, days + 2):
        cur = by_day[d]
        for (mask, used), val in cur.items():
            if mask != full:
                t1 = t3 = 0
                fs = list(val[4])
                ff = list(val[5])
                for j in range(n):
                    if not (mask >> j) & 1:
                        t1 += reqs[j]["deferral_penalty"]
                        t3 += 1
                        fs[j] = days + 1
                        ff[j] = days + 1
                fin = (val[0] + t1 * m23 + t3, val[1] + t1, val[2], val[3] + t3,
                       tuple(fs), tuple(ff))
            else:
                fin = val
            if used not in best or fin < best[used]:
                best[used] = fin
            if d > days:
                continue
            # idle one day
            nx = by_day[d + 1]
            key = (mask, used)
            if key not in nx or val < nx[key]:
                nx[key] = val
            for j in range(n):
                if (mask >> j) & 1:
                    continue
                r = reqs[j]
                if d < r["avail"]:
                    continue
                pub = r["pub_idx"]
                for shifts, startset, length in opts[j]:
                    if used + shifts > pool or d not in startset:
                        continue
                    f = d + length - 1
                    over = max(0, f - r["due_idx"])
                    t1 = over * r["overdue_weight"]
                    t2 = length * r["revenue_per_day"] + r["shift_cost"] * shifts
                    t3 = 0 if d == pub else 1
                    nv = (val[0] + t1 * m23 + t2 * m3 + t3, val[1] + t1, val[2] + t2,
                          val[3] + t3,
                          val[4][:j] + (d,) + val[4][j + 1:],
                          val[5][:j] + (f,) + val[5][j + 1:])
                    k2 = (mask | (1 << j), used + shifts)
                    slot = by_day[f + 1]
                    if k2 not in slot or nv < slot[k2]:
                        slot[k2] = nv
    return best


orig = dr.plan_base


def checked(reqs, days, pool, m3, m23):
    a = orig(reqs, days, pool, m3, m23)
    b = reference(reqs, days, pool, m3, m23)
    if a != b:
        ka, kb = set(a), set(b)
        print("MISMATCH base with", [r["request_id"] for r in reqs])
        for k in sorted(ka | kb):
            if a.get(k) != b.get(k):
                print("  k=%s fast=%s ref=%s" % (k, a.get(k), b.get(k)))
        raise SystemExit(1)
    print("ok base", [r["request_id"] for r in reqs], "k values:", len(a))
    return a


dr.plan_base = checked
sys.exit(dr.main(["x", sys.argv[1], sys.argv[2]]))

